import fs from "fs";
import path from "path";

console.log("🎨 Gerando ícones PNG autênticos 2D Minimalista IURD...");

const publicDir = path.resolve("public");
if (!fs.existsSync(publicDir)) {
  fs.mkdirSync(publicDir, { recursive: true });
}

const icons = [
  { name: "public/icon-192.png", b64: "" },
  { name: "public/icon-512.png", b64: "" },
  { name: "public/apple-touch-icon.png", b64: "" },
  { name: "public/favicon.png", b64: "" }
];

icons.forEach(({ name, b64 }) => {
  const buf = Buffer.from(b64, "base64");
  fs.writeFileSync(path.resolve(name), buf);
  console.log("  ✓ Criado " + name + " (" + (buf.length / 1024).toFixed(2) + " KB) - Header: " + buf.toString("hex", 0, 4));
});

console.log("✨ Ícones 2D minimalistas gerados com sucesso!\n");
